from pathlib import Path
import sqlite3,json,hashlib
r=Path(__file__).resolve().parents[4];p=Path(__file__).parent;db=Path('/private/tmp/atlas-duncan-integration-v2/site-v1/atlas.sqlite');mid='duncan-chang-1970-endpoint-average';sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();c=sqlite3.connect(db);definition=json.loads((r/'models'/(mid+'.json')).read_text());row=c.execute('SELECT definition_json,executable FROM models WHERE id=?',(mid,)).fetchone();assert json.loads(row[0])==definition and row[1]==1
reg=json.loads((r/'catalogue/approved-models.json').read_text());approval=next(a for a in reg['models'] if a['model_id']==mid);a=c.execute('SELECT record_json FROM model_approvals WHERE model_id=?',(mid,)).fetchall();assert len(a)==1 and json.loads(a[0][0])==approval
review=c.execute('SELECT path,sha256,record_json FROM agent_reviews WHERE model_id=?',(mid,)).fetchall();assert len(review)==1;path,h,raw=review[0];assert path==approval['review']['path'] and h==approval['review']['sha256'] and sha(r/path)==h and json.loads(raw)==json.loads((r/path).read_text());sources=c.execute('SELECT url,locator,role FROM sources WHERE model_id=?',(mid,)).fetchall();assert any(x[0]=='https://doi.org/10.1061/JSFEAQ.0001458' for x in sources);foreign=c.execute('PRAGMA foreign_key_check').fetchall();assert not foreign
(p/'database-check-v1.json').write_text(json.dumps({'status':'passed','database_sha256':sha(db),'definition':'exact_current_JSON','definition_sha256':approval['definition']['sha256'],'approval_id':approval['id'],'review_path':path,'review_sha256':h,'sources':sources,'foreign_key_errors':foreign},indent=2)+'\n');print('Exactmodel/approval/review/source/foreignkeys database PASS')
